var t=`1304-beijinho`;var r=`world-1304`;var o=`BR`;var n=`south-america`;var d=8;var a=78;var s={en:`Beijinho`,ua:`Бейжинью`};var u={en:`Beijinho is a dish from Brazil featuring sweetened condensed milk, desiccated coconut. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Бейжинью, страва кухні країни Бразилія з такими основними складниками: згущене молоко з цукром, кокосова стружка. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var c=[{en:`Simmer the liquid and flavorings uncovered for about 15 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 15 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:15,i:[[`sweetened-condensed-milk`,390,`g`],[`unsalted-butter`,35,`g`],[`desiccated-coconut`,180,`g`]]},{en:`Refrigerate the prepared mixture for about 45 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 45 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:45,i:[]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:13,i:[]},{en:`Roll the cooled coconut-condensed-milk mixture into bite-sized sweets and coat with sugar; keep refrigerated.`,ua:`Скачайте охолоджену кокосово-молочну масу в невеликі цукерки, обкачайте в цукрі та тримайте в холодильнику.`,t:[`standard-breading`],m:5,i:[[`white-granulated-sugar`,95,`g`],[`ground-cloves`,1,`g`]]}];var g={slug:t,id:r,country:`BR`,region:n,servings:8,minutes:78,title:s,text:u,steps:c};export{o as country,g as default,r as id,a as minutes,n as region,d as servings,t as slug,c as steps,u as text,s as title};